contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with inputs: caller will be this contract
    function run(address initialOwner, address newOwner) public payable {
        require(initialOwner != address(0) && newOwner != address(0));

        // Set up initial owner by calling transferOwnership from this contract only if possible.
        // The freshly deployed c has some owner value; we need to ensure owner == initialOwner
        // To do that, if current owner is this contract, we can set it; otherwise we can't change it.
        // First read the current owner.
        address beforeOwner = c.owner();

        // If this contract is the owner, set owner to initialOwner so test covers both branches.
        if (beforeOwner == address(this)) {
            // this call changes state; must be a top-level statement
            c.transferOwnership(initialOwner);
        }

        // Read owner after possible setup
        address ownerAfterSetup = c.owner();

        // Now attempt to transfer ownership to newOwner and record whether it reverted.
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Final owner observable
        address finalOwner = c.owner();

        // General rule:
        // - If the transfer call reverted, owner did not change (finalOwner == ownerAfterSetup).
        // - If it did not revert, owner equals newOwner.
        assert(reverted ? finalOwner == ownerAfterSetup : finalOwner == newOwner);
    }

    receive() external payable { }
}

